=== reservations/PriceCalculator.java
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	
     9	/**
    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    12	 * (half-even) at every step.
    13	 */
    14	public final class PriceCalculator {
    15	
    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    18	
    19	    private final ChildPricingPolicy childPricing = new FreeChildren();
    20	
    21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
    22	        return calculate(room, checkIn, checkOut, ratePlan, 0);
    23	    }
    24	
    25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, int children) {
    26	        int nights = 0;
    27	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    28	        BigDecimal childrenPerNight = childPricing.pricePerChildPerNight().multiply(BigDecimal.valueOf(children));
    29	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    30	            subtotal = subtotal.add(nightPrice(room, night)).add(cents(childrenPerNight));
    31	            nights++;
    32	        }
    33	        BigDecimal discount = switch (ratePlan) {
    34	            case STANDARD -> cents(BigDecimal.ZERO);
    35	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    36	        };
    37	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    38	    }
    39	
    40	    BigDecimal nightPrice(Room room, LocalDate night) {
    41	        BigDecimal nightlyRate = room.nightlyRate();
    42	        if (isHighSeason(night)) {
    43	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    44	        }
    45	        return cents(nightlyRate);
    46	    }
    47	
    48	    /** High season: from December 15 to the end of February, and the whole of July. */
    49	    static boolean isHighSeason(LocalDate date) {
    50	        Month month = date.getMonth();
    51	        return month == Month.JANUARY
    52	                || month == Month.FEBRUARY
    53	                || month == Month.JULY
    54	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    55	    }
    56	
    57	    static BigDecimal cents(BigDecimal value) {
    58	        return value.setScale(2, RoundingMode.HALF_EVEN);
    59	    }
    60	}
