    18	    private BigDecimal amountPaid;
    19	    private BigDecimal refund;
    20	
    21	    Reservation(long id, NewReservation request, Price price) {
    22	        this.id = id;
    23	        this.roomNumber = request.roomNumber();
    24	        this.guest = request.guest();
    25	        this.checkIn = request.checkIn();
    26	        this.checkOut = request.checkOut();
    27	        this.guests = request.guests();
    28	        this.children = request.children();
    29	        this.ratePlan = request.ratePlan();
    30	        this.price = price;
    31	        this.status = ReservationStatus.PENDING;
    32	        this.amountPaid = PriceCalculator.cents(BigDecimal.ZERO);
    33	    }
