    53	    }
    54	
    55	    public int guests() {
    56	        return guests;
    57	    }
    58	
    59	    /** Children up to 12 years old: they do not pay, but take a place in the room. */
    60	    public int children() {
    61	        return children;
    62	    }
    63	
    64	    public RatePlan ratePlan() {
    65	        return ratePlan;
    66	    }
    67	
    68	    public Price price() {
    69	        return price;
    70	    }
    71	
    72	    public ReservationStatus status() {
    73	        return status;
    74	    }
    75	
    76	    /** What the guest paid: the total, once the reservation is confirmed; zero before that. */
    77	    public BigDecimal amountPaid() {
    78	        return amountPaid;
    79	    }
    80	
    81	    /** What the guest got back when the reservation was cancelled; null while it is not cancelled. */
    82	    public BigDecimal refund() {
    83	        return refund;
    84	    }
    85	
    86	    /** Confirmed, checked in or checked out: the guest paid and the room is theirs. */
    87	    public boolean isPaid() {
    88	        return status == ReservationStatus.CONFIRMED
    89	                || status == ReservationStatus.CHECKED_IN
    90	                || status == ReservationStatus.CHECKED_OUT;
    91	    }
    92	
    93	    /** The money the inn keeps from this reservation. */
    94	    public BigDecimal amountKept() {
    95	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    96	    }
    97	
    98	    void changeStatus(ReservationStatus newStatus) {
    99	        this.status = newStatus;
   100	    }
   101	
   102	    void confirmPayment() {
   103	        this.status = ReservationStatus.CONFIRMED;
   104	        this.amountPaid = price.total();
   105	    }
