     9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    10	public final class ReservationService {
    11	
    12	    static final String HOTEL_NAME = "Pousada Maré Alta";
    13	
    14	    private final Rooms rooms;
    15	    private final ReservationStore store;
    16	    private final PriceCalculator priceCalculator;
    17	    private final EmailSender emailSender;
    18	
    19	    public ReservationService(
    20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    21	        this.rooms = rooms;
    22	        this.store = store;
    23	        this.priceCalculator = priceCalculator;
    24	        this.emailSender = emailSender;
    25	    }
    26	
    27	    public synchronized Reservation create(NewReservation request) {
    28	        if (!request.checkOut().isAfter(request.checkIn())) {
    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    30	        }
    31	        if (request.guests() < 1) {
    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    33	        }
    34	        if (request.children() < 0) {
    35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the number of children cannot be negative");
    36	        }
    37	        Room room = rooms.find(request.roomNumber())
    38	                .orElseThrow(() -> new HotelException(
    39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    40	        if (request.guests() + request.children() > room.capacity()) {
    41	            throw new HotelException(
    42	                    ErrorCode.CAPACITY_EXCEEDED,
    43	                    "room " + room.number() + " takes at most " + room.capacity() + " people, children included");
    44	        }
    45	        boolean roomTaken = store.all().stream()
    46	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    47	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    48	        if (roomTaken) {
    49	            throw new HotelException(
    50	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    51	        }
    52	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan(),
    53	                request.children());
    54	        Reservation reservation = new Reservation(store.nextId(), request, price);
    55	        store.save(reservation);
    56	        return reservation;
    57	    }
    58	
    59	    public Reservation find(long reservationId) {
    60	        return store.find(reservationId)
    61	                .orElseThrow(() -> new HotelException(
    62	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    63	    }
    64	
    65	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    66	    public synchronized Reservation confirm(long reservationId) {
    67	        Reservation reservation = find(reservationId);
    68	        if (reservation.status() != ReservationStatus.PENDING) {
    69	            throw notAllowed(reservation, "confirm");
    70	        }
    71	        reservation.confirmPayment();
    72	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    73	        emailSender.send(
    74	                reservation.guest().email(),
    75	                "Reserva confirmada - " + HOTEL_NAME,
    76	                confirmationEmailBody(reservation, receipt));
    77	        return reservation;
    78	    }
    79	
    80	    /**
    81	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    82	     * reservation was never paid, so nothing comes back).
    83	     */
    84	    public synchronized Reservation cancel(long reservationId) {
    85	        Reservation reservation = find(reservationId);
    86	        if (reservation.status() != ReservationStatus.PENDING
    87	                && reservation.status() != ReservationStatus.CONFIRMED) {
    88	            throw notAllowed(reservation, "cancel");
    89	        }
    90	        BigDecimal refund = switch (reservation.ratePlan()) {
    91	            case STANDARD -> reservation.amountPaid();
    92	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    93	        };
    94	        reservation.cancel(refund);
    95	        return reservation;
    96	    }
    97	
    98	    public synchronized Reservation checkIn(long reservationId) {
    99	        Reservation reservation = find(reservationId);
   100	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   101	            throw notAllowed(reservation, "check in");
   102	        }
   103	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   104	        return reservation;
   105	    }
   106	
   107	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   108	    public synchronized ReservationReceipt checkOut(long reservationId) {
   109	        Reservation reservation = find(reservationId);
   110	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   111	            throw notAllowed(reservation, "check out");
   112	        }
   113	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   114	        return new ReservationReceipt(reservation, roomOf(reservation));
   115	    }
   116	
   117	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   118	    public ReservationReceipt receiptCopy(long reservationId) {
   119	        Reservation reservation = find(reservationId);
   120	        if (!reservation.isPaid()) {
   121	            throw notAllowed(reservation, "issue a receipt for");
   122	        }
   123	        return new ReservationReceipt(reservation, roomOf(reservation));
   124	    }
   125	
   126	    private Room roomOf(Reservation reservation) {
   127	        return rooms.find(reservation.roomNumber()).orElseThrow();
   128	    }
   129	
   130	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   131	        return "Olá, " + reservation.guest().name() + "!\n\n"
   132	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   133	                + receipt.text() + "\n"
   134	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   135	                + "Até breve!\n";
   136	    }
